export const documentsRegister = new Command("documents-register")
  .description(
    commandDescriptions["documentsRegister"] ??
      `The records a buyer is sent, and the one question this app exists to answer: which document belongs to which transaction. A document is an invoice, a delivery note, a credit note or a return receipt — filed against a transaction (\`entity_type\` + \`entity_id\`, and \`order\` is the only owner accepted today), carrying the \`number\` a customer quotes on the phone, and pointing at bytes it never holds: \`source\` decides whether the file is an asset of this platform (\`storage_asset_id\`) or a file on the tenant's own host (\`external_url\`), and a database CHECK pairs the two so neither can be half-filled. Nothing here produces a document and nothing here serves one — a finance system issues them, this records what was issued. The column to read twice is \`visibility\`: an \`internal\` document is answered to an operator and NEVER to a storefront caller, which is confined to the customer ones in the query itself, so an internal row is missing from its list, missing from its page total and a 404 at its own address.`,
  )
  .configureHelp({
    helpWidth: process.stdout.columns || 80,
  });

